//https://www.shadertoy.com/view/4lsXDN
float sdEllipse(vec2 p, vec2 ab)
{
	p = abs( p );
    vec2 q = ab*(p-ab);
	float w = (q.x<q.y)? 1.570796327 : 0.0;
    for( int i=0; i<5; i++ )
    {
        vec2 cs = vec2(cos(w),sin(w));
        vec2 u = ab*vec2( cs.x,cs.y);
        vec2 v = ab*vec2(-cs.y,cs.x);
        w = w + dot(p-u,v)/(dot(p-u,u)+dot(v,v));
    }
    float d = length(p-ab*vec2(cos(w),sin(w)));
    return (dot(p/ab,p/ab)>1.0) ? d : -d;
}

bool isContact(vec2 c1, vec2 r1, vec2 c2, vec2 r2)
{
    vec2 p = (c2 - c1) / r2;
    vec2 r = r1 / r2;
    float d = sdEllipse(p, r) - 1.0;
    return d < 0.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;

    vec2 c1 = vec2(-0.5, -0.1) + vec2(cos(iTime), sin(iTime)) * 0.3;
    vec2 r1 = vec2(0.3, 0.9) + vec2(sin(iTime * 0.5), cos(iTime * 0.5)) * 0.3;
    vec2 c2 = vec2(0.2, 0.1) + vec2(sin(iTime), cos(iTime)) * 0.4;
    vec2 r2 = vec2(0.5, 0.2) + vec2(cos(iTime * 0.7), sin(iTime * 0.7)) * 0.2;
    float d = sdEllipse(p - c1, r1);
    d = min(d, sdEllipse(p - c2, r2));


    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : isContact(c1, r1, c2, r2) ? vec3(1.0,0.65,0.85) : vec3(0.65,0.85,1.0);
    col *= 1.0 - exp(-7.0*abs(d));
    col *= 0.8 + 0.2 * cos(160.0*abs(d));
    col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.015,abs(d)) );

	fragColor = vec4(col, 1.0);
}
